        dp_cur = [[-10**18] * (N + 1) for _ in range(N + 1)]
        # i1 ranges such that j1 = s - i1 is between 1 and N
        i_min = max(1, s - N)
        i_max = min(N, s - 1)
        for i1 in range(i_min, i_max + 1):
            j1 = s - i1
            if j1 < 1 or j1 > N:
                continue
            for i2 in range(i_min, i_max + 1):
                j2 = s - i2
                if j2 < 1 or j2 > N:
                    continue
                best_prev = -10**18
                # possibilities from previous step where each moved from up or left
                for di1 in (0, 1):  # 0: came from left (i same), 1: came from up (i-1)
                    for di2 in (0, 1):
                        pi1 = i1 - di1
                        pi2 = i2 - di2
                        pj1 = j1 - (1 - di1)
                        pj2 = j2 - (1 - di2)
                        if pi1 < 1 or pj1 < 1 or pi2 < 1 or pj2 < 1:
                            continue
                        val = dp_prev[pi1][pi2]
                        if val > best_prev:
                            best_prev = val
                if best_prev == -10**18:
                    continue
                add = 0
                if i1 == i2 and j1 == j2:
                    add = grid[i1][j1]
                else:
                    add = grid[i1][j1] + grid[i2][j2]
                dp_cur[i1][i2] = best_prev + add
        dp_prev = dp_cur

    return dp_prev[N][N] if dp_prev[N][N] > -10**18 else 0

