def max_product(num_str: str, N: int, K: int) -> int:
    if K == 0:
        return int(num_str)
    if K > N - 1:
        return 0

    # Precompute prefix integer values and powers of 10
    prefix = [0] * N
    pow10 = [1] * (N + 1)
    for i in range(1, N + 1):
        pow10[i] = pow10[i - 1] * 10

    for i, ch in enumerate(num_str):
        digit = ord(ch) - 48
        if i == 0:
            prefix[i] = digit
        else:
            prefix[i] = prefix[i - 1] * 10 + digit

    def substring_value(l: int, r: int) -> int:
        if l == 0:
            return prefix[r]
        return prefix[r] - prefix[l - 1] * pow10[r - l + 1]

    # dp[i][k] = max product for prefix ending at i with k cuts
    dp = [[0] * (K + 1) for _ in range(N)]
    for i in range(N):
        dp[i][0] = substring_value(0, i)

    for k in range(1, K + 1):
        # prefix length must be at least k to place k cuts
        for i in range(k, N):
            best = 0
            # previous cut at position j (end of previous segment)
            for j in range(k - 1, i):
                prod = dp[j][k - 1] * substring_value(j + 1, i)
                if prod > best:
                    best = prod
            dp[i][k] = best

    return dp[N - 1][K]

