def select_volunteers(n: int, m: int, applicants: List[Tuple[int, int]]) -> Tuple[int, List[Tuple[int, int]]]:
    # Sort applicants by score descending, then registration number ascending
    sorted_applicants = sorted(applicants, key=lambda x: (-x[1], x[0]))

    # Number of slots to consider for cutoff
    k = int(1.5 * m)
    # Ensure k does not exceed number of applicants
    if k > n:
        k = n
    if k <= 0 or n == 0:
        return (0, [])

    # Determine cutoff score (score of kth highest applicant, 1-indexed)
    cutoff = sorted_applicants[k - 1][1]

    # All applicants with score >= cutoff are qualified
    qualified = [p for p in sorted_applicants if p[1] >= cutoff]

    return (cutoff, qualified)

