def count_coprime_pairs(x0: int, y0: int) -> int:
    if y0 % x0 != 0:
        return 0
    t = y0 // x0
    count = 0
    from math import isqrt, gcd
    for a in range(1, isqrt(t) + 1):
        if t % a == 0:
            b = t // a
            if gcd(a, b) == 1:
                count += 1 if a == b else 2
    return count

