def is_prime(num: int) -> bool:
    """
    Determine whether `num` is a prime number.

    Args:
        num (int): The integer to check for primality.

    Returns:
        bool: True if `num` is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    """Generate all unique numbers from n by applying digit transformation rules.

    Each rule (x, y) allows digit x to be transformed into digit y.
    Starting from the original integer n, we repeatedly apply any single
    digit transformation to produce new numbers. A breadth‑first search
    explores the space of reachable numbers and returns the count of
    distinct numbers that can be generated (including the starting number).
    """
    # Build mapping from digit to possible transformed digits
    mapping = {}
    for x, y in rules:
        sx, sy = str(x), str(y)
        if sx not in mapping:
            mapping[sx] = set()
        mapping[sx].add(sy)

    visited = {n}
    queue = [n]

    while queue:
        cur = queue.pop(0)
        s = str(cur)
        for i, ch in enumerate(s):
            if ch in mapping:
                for new_ch in mapping[ch]:
                    new_s = s[:i] + new_ch + s[i+1:]
                    new_num = int(new_s)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine if a statement concerns a day of week
    def ignores_day(stmt: str) -> bool:
        lower_stmt = stmt.lower()
        return any(day.lower() in lower_stmt for day in days_of_week)

    # Helper to evaluate truth value of a statement
    def eval_truth(speaker: str, stmt: str) -> bool:
        # Remove trailing punctuation and standardize spacing
        stmt_clean = stmt.strip().rstrip('.').lower()

        # Handle "I am guilty" / "I am not guilty"
        if stmt_clean.startswith("i am "):
            if stmt_clean.endswith("guilty"):
                return speaker == scenario
            elif stmt_clean.endswith("not guilty"):
                return speaker != scenario

        # Handle "<name> is guilty" / "<name> is not guilty"
        if " is guilty" in stmt_clean:
            subject = stmt_clean.split(" is guilty")[0].strip()
            return subject == scenario
        if " is not guilty" in stmt_clean:
            subject = stmt_clean.split(" is not guilty")[0].strip()
            return subject != scenario

        # If statement does not match expected patterns, treat it as neutral/irrelevant
        return True

    # Iterate over all participants and their statements
    for speaker, stmts in statements.items():
        is_liar = speaker in liar_count
        for stmt in stmts:
            if ignores_day(stmt):
                continue  # Skip statements about days of the week
            truth = eval_truth(speaker, stmt)
            if is_liar and truth:
                return False  # Liars should not tell truths
            if not is_liar and not truth:
                return False  # Truthful speakers must tell truth
    return True

def check_scenario(scenario, liar_count, statements, days_of_week):

    liars = liar_count

    days_upper = set(d.upper() for d in days_of_week)

    for speaker, stmts in statements.items():
        for stmt in stmts:
            # skip None etc.
            if not isinstance(stmt, str):
                continue
            # if contains any day token as word
            # find words
            for word in re.findall(r"\b\w+\b", stmt.upper()):
                if word in days_upper:
                    break
            else:
                # not a day statement
                # evaluate
                normalized = stmt.rstrip('.').strip().lower()
                # skip empty 
                if not normalized:
                    continue

                # analyze
                # handle self statements first
                if normalized == "i am guilty":
                    subject = speaker
                    guilty = True
                elif normalized == "i am not guilty":
                    subject = speaker
                    guilty = False
                else:
                    parts = normalized.split()
                    if len(parts) == 3 and parts[1] == "is" and parts[2] == "guilty":
                        subject = parts[0]
                        guilty = True
                    elif len(parts) == 4 and parts[1] == "is" and parts[2] == "not" and parts[3] == "guilty":
                        subject = parts[0]
                        guilty = False
                    else:
                        # can't parse; ignore
                        continue

                # Determine actual truth value
                is_true = (subject == scenario) if guilty else (subject != scenario)

                # Check consistency
                if (speaker in liars and is_true) or (speaker not in liars and not is_true):
                    return False
    return True

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Disregards any statements that include a day of the week.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    def stmt_is_true(stmt: str, speaker: str) -> bool:
        s = stmt.strip().rstrip('.').lower()
        # Handle "I am guilty/not guilty"
        if s.startswith("i am"):
            is_guilty = "not" not in s
            return (speaker == scenario) if is_guilty else (speaker != scenario)
        # Handle "X is guilty/not guilty"
        parts = s.split()
        if len(parts) < 3 or parts[1] != "is":
            return False
        witness = parts[0].upper()
        if parts[2] == "guilty":
            return witness == scenario
        if parts[2] == "not" and len(parts) >= 4 and parts[3] == "guilty":
            return witness != scenario
        return False

    # Lowercase days for quick check
    days_lower = {d.lower() for d in days_of_week}

    for speaker, stmts in statements.items():
        for stmt in stmts:
            stmt_lower = stmt.lower()
            # Skip statements that mention a day
            if any(day in stmt_lower for day in days_lower):
                continue
            truth = stmt_is_true(stmt, speaker)
            # Determine if speaker is expected truthfulness
            if speaker in liar_count:
                if truth:
                    return False
            else:
                if not truth:
                    return False
    return True

