def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    """
    Compute the maximum value of herbs that can be collected within the time limit T.
    Each herb can be taken at most once.
    Uses 0/1 knapsack DP with time as the weight dimension.
    """
    dp = [0] * (T + 1)

    for time, value in herbs:
        if time > T:
            continue
        # Traverse capacities backwards to avoid reuse of the same item
        for cap in range(T, time - 1, -1):
            new_val = dp[cap - time] + value
            if new_val > dp[cap]:
                dp[cap] = new_val

    return max(dp)

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
