def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # dp[j] will be True if volume j can be achieved
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in volumes:
        if vol > V:
            continue
        for j in range(V, vol - 1, -1):
            if dp[j - vol]:
                dp[j] = True
    best = 0
    for j in range(V, -1, -1):
        if dp[j]:
            best = j
            break
    return V - best

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    # Quick feasibility check
    if m > sum(a):
        return 0
    dp = [0] * (m + 1)
    dp[0] = 1
    for i in range(n):
        limit = a[i]
        new = [0] * (m + 1)
        prefix = [0] * (m + 1)
        prefix[0] = dp[0]
        for s in range(1, m + 1):
            prefix[s] = (prefix[s - 1] + dp[s]) % MOD
        for s in range(m + 1):
            lo = s - limit
            if lo <= 0:
                new[s] = prefix[s] % MOD
            else:
                new[s] = (prefix[s] - prefix[lo - 1]) % MOD
        dp = new
    return dp[m] % MOD

